from sympy import symbols, solve

x = symbols("x", real=True)

def sign(v):
    if v > 0:
        return "+"
    return "-"

def report(a, b, c, d, e):
    f = lambda t: a*t**4 + b*t**3 + c*t**2 + d*t + e
    fp = lambda t: 4*a*t**3 + 3*b*t**2 + 2*c*t + d
    print(f"f(x) = {f(x)}")
    crit = sorted(solve(fp(x), x))
    if len(crit) == 0:
        if fp(0) > 0:
            print("no critical points, increasing")
        else:
            print("no critical points, decreasing")
        return
    tests = [crit[0] - 1]
    for i in range(len(crit) - 1):
        tests.append((crit[i] + crit[i + 1]) / 2)
    tests.append(crit[len(crit) - 1] + 1)
    for i in range(len(crit)):
        left = sign(fp(tests[i]))
        right = sign(fp(tests[i + 1]))
        kind = "neither"
        if left == "+" and right == "-":
            kind = "local max"
        if left == "-" and right == "+":
            kind = "local min"
        print(f"x = {crit[i]}: {kind}, f = {f(crit[i])}")

k = int(input())
for i in range(k):
    # split() cuts the line at its spaces into a list of texts
    a, b, c, d, e = [int(v) for v in input().split()]
    report(a, b, c, d, e)

