from sympy import symbols, factor, solve

x = symbols("x", real=True)

def sign(v):
    if v > 0:
        return "+"
    return "-"

def test_points(cuts):
    tests = [cuts[0] - 1]
    for i in range(len(cuts) - 1):
        tests.append((cuts[i] + cuts[i + 1]) / 2)
    tests.append(cuts[len(cuts) - 1] + 1)
    return tests

def concavity(label, f, fp, fpp):
    print(label)
    print(f"  f''(x) = {factor(fpp(x))}   (differentiate twice, then factor)")
    cands = sorted(solve(fpp(x), x))
    if len(cands) == 0:
        print(f"  f'' is never 0, and f''(0) = {fpp(0)}: no inflection points")
    else:
        tests = test_points(cands)
        for i in range(len(cands)):
            c = cands[i]
            left = sign(fpp(tests[i]))
            right = sign(fpp(tests[i + 1]))
            if left != right:
                print(f"  x = {c}: f'' goes {left} to {right}, inflection point ({c}, {f(c)})")
            else:
                print(f"  x = {c}: f'' stays {left}, not an inflection point")
    for c in sorted(solve(fp(x), x)):
        v = fpp(c)
        if v > 0:
            print(f"  critical x = {c}: f'' = {v} > 0, local min f = {f(c)}")
        elif v < 0:
            print(f"  critical x = {c}: f'' = {v} < 0, local max f = {f(c)}")
        else:
            print(f"  critical x = {c}: f'' = 0, the test says nothing")

concavity("Example 1 · the plain case: x^3 - 3x",
          lambda t: t**3 - 3*t, lambda t: 3*t**2 - 3, lambda t: 6*t)
concavity("Example 2 · two inflection points: x^4 - 6x^2",
          lambda t: t**4 - 6*t**2, lambda t: 4*t**3 - 12*t, lambda t: 12*t**2 - 12)
concavity("Example 3 · the trap: x^4",
          lambda t: t**4, lambda t: 4*t**3, lambda t: 12*t**2)
concavity("Example 5 · no inflection points: x^4 + x^2",
          lambda t: t**4 + t**2, lambda t: 4*t**3 + 2*t, lambda t: 12*t**2 + 2)
concavity("Example 8 · a cubic: 2x^3 - 9x^2 + 12x",
          lambda t: 2*t**3 - 9*t**2 + 12*t, lambda t: 6*t**2 - 18*t + 12, lambda t: 12*t - 18)

