from sympy import symbols, solve, expand, limit, oo

x = symbols("x", real=True)

def sign(v):
    if v > 0:
        return "+"
    return "-"

def test_points(cuts):
    tests = [cuts[0] - 1]
    for i in range(len(cuts) - 1):
        tests.append((cuts[i] + cuts[i + 1]) / 2)
    tests.append(cuts[len(cuts) - 1] + 1)
    return tests

def changes(g):
    # The points where g is 0 and its sign changes, with the sign on each side.
    cuts = sorted(solve(g(x), x))
    found = []
    if len(cuts) > 0:
        tests = test_points(cuts)
        for i in range(len(cuts)):
            left = sign(g(tests[i]))
            right = sign(g(tests[i + 1]))
            if left != right:
                found.append([cuts[i], left, right])
    return found

def sketch(label, f, fp, fpp):
    print(label)
    print(f"  intercepts: f(0) = {f(0)}, f(x) = 0 at {sorted(solve(f(x), x))}")
    if expand(f(-x) - f(x)) == 0:
        print("  symmetry: f(-x) = f(x), even")
    elif expand(f(-x) + f(x)) == 0:
        print("  symmetry: f(-x) = -f(x), odd")
    else:
        print("  symmetry: neither")
    print(f"  ends: f -> {limit(f(x), x, -oo)} on the left, {limit(f(x), x, oo)} on the right")
    for c, left, right in changes(fp):
        if left == "+":
            print(f"  f' goes + to - at {c}: local max ({c}, {f(c)})")
        else:
            print(f"  f' goes - to + at {c}: local min ({c}, {f(c)})")
    for c, left, right in changes(fpp):
        print(f"  f'' goes {left} to {right} at {c}: inflection point ({c}, {f(c)})")

sketch("Example 1 · a cubic: x^3 - 3x^2",
       lambda t: t**3 - 3*t**2, lambda t: 3*t**2 - 6*t, lambda t: 6*t - 6)
sketch("Example 2 · symmetry: x^4 - 4x^2",
       lambda t: t**4 - 4*t**2, lambda t: 4*t**3 - 8*t, lambda t: 12*t**2 - 8)
sketch("Example 3 · an odd function: 12x - x^3",
       lambda t: 12*t - t**3, lambda t: 12 - 3*t**2, lambda t: -6*t)
sketch("Example 6 · a flat inflection point: x^4 - 4x^3",
       lambda t: t**4 - 4*t**3, lambda t: 4*t**3 - 12*t**2, lambda t: 12*t**2 - 24*t)
sketch("Example 7 · the drone: 6t^2 - t^3",
       lambda t: 6*t**2 - t**3, lambda t: 12*t - 3*t**2, lambda t: 12 - 6*t)

