x = symbols("x", real=True)

def sign(v):
    if v > 0:
        return "+"
    return "-"

def test_points(cuts):
    tests = [cuts[0] - 1]
    for i in range(len(cuts) - 1):
        tests.append((cuts[i] + cuts[i + 1]) / 2)
    tests.append(cuts[len(cuts) - 1] + 1)
    return tests

def changes(g):
    cuts = sorted(solve(g(x), x))
    found = []
    if len(cuts) > 0:
        tests = test_points(cuts)
        for i in range(len(cuts)):
            left = sign(g(tests[i]))
            right = sign(g(tests[i + 1]))
            if left != right:
                found.append([cuts[i], left, right])
    return found

def report(a, b, c, d, e):
    f = lambda t: a*t**4 + b*t**3 + c*t**2 + d*t + e
    fp = lambda t: 4*a*t**3 + 3*b*t**2 + 2*c*t + d
    fpp = lambda t: 12*a*t**2 + 6*b*t + 2*c
    print(f"f(x) = {f(x)}")
    print(f"intercepts: {f(0)} and {sorted(solve(f(x), x))}")
    if expand(f(-x) - f(x)) == 0:
        print("even")
    elif expand(f(-x) + f(x)) == 0:
        print("odd")
    else:
        print("neither even nor odd")
    print(f"ends: {limit(f(x), x, -oo)} and {limit(f(x), x, oo)}")
    for p, left, right in changes(fp):
        if left == "+":
            print(f"local max ({p}, {f(p)})")
        else:
            print(f"local min ({p}, {f(p)})")
    for p, left, right in changes(fpp):
        print(f"inflection point ({p}, {f(p)})")

k = int(input())
for i in range(k):
    # split() cuts the line at its spaces into a list of texts
    a, b, c, d, e = [int(v) for v in input().split()]
    report(a, b, c, d, e)
